32	    public static Product toProduct(CatalogItemEntity entity) {
33	        Product prod = new Product();
34	        prod.setItemId(entity.getItemId());
35	        prod.setName(entity.getName());
36	        prod.setDesc(entity.getDesc());
37	        prod.setPrice(entity.getPrice());
38	        if (entity.getInventory() != null) {
39	            prod.setLocation(entity.getInventory().getLocation());
40	            prod.setLink(entity.getInventory().getLink());
41	            prod.setQuantity(entity.getInventory().getQuantity());
42	        } else {
43	            log.warning("Inventory for " + entity.getName() + "[" + entity.getItemId() + "] unknown and missing; quantity set to 0");
44	            prod.setQuantity(0);
45	            prod.setLocation("unknown");
46	        }
47	        return prod;
48	    }
