50	    public static String shoppingCartToJson(ShoppingCart cart) {
51	        JsonArrayBuilder cartItems = Json.createArrayBuilder();
52	        cart.getShoppingCartItemList().forEach(item -> {
53	            cartItems.add(Json.createObjectBuilder()
54	                .add("productSku",item.getProduct().getItemId())
55	                .add("quantity",item.getQuantity())
56	            );
57	        });
58	
59	        int randomNameAndEmailIndex = ThreadLocalRandom.current().nextInt(RANDOM_NAMES.length);
60	
61	        JsonObject jsonObject = Json.createObjectBuilder()
62	            .add("orderValue", Double.valueOf(cart.getCartTotal()))
63	            .add("customerName",RANDOM_NAMES[randomNameAndEmailIndex])
64	            .add("customerEmail",RANDOM_EMAILS[randomNameAndEmailIndex])
65	            .add("retailPrice", cart.getShoppingCartItemList().stream().mapToDouble(i -> i.getQuantity()*i.getPrice()).sum())
66	            .add("discount", Double.valueOf(cart.getCartItemPromoSavings()))
67	            .add("shippingFee", Double.valueOf(cart.getShippingTotal()))
68	            .add("shippingDiscount", Double.valueOf(cart.getShippingPromoSavings()))
69	            .add("items",cartItems) 
70	            .build();
71	        StringWriter w = new StringWriter();
72	        try (JsonWriter writer = Json.createWriter(w)) {
73	            writer.write(jsonObject);
74	        }
75	        return w.toString();
76	    }
