78	    public static Order jsonToOrder(String json) {
79	        JsonReader jsonReader = Json.createReader(new StringReader(json));
80	        JsonObject rootObject = jsonReader.readObject();
81	        Order order = new Order();
82	        order.setCustomerName(rootObject.getString("customerName"));
83	        order.setCustomerEmail(rootObject.getString("customerEmail"));
84	        order.setOrderValue(rootObject.getJsonNumber("orderValue").doubleValue());
85	        order.setRetailPrice(rootObject.getJsonNumber("retailPrice").doubleValue());
86	        order.setDiscount(rootObject.getJsonNumber("discount").doubleValue());
87	        order.setShippingFee(rootObject.getJsonNumber("shippingFee").doubleValue());
88	        order.setShippingDiscount(rootObject.getJsonNumber("shippingDiscount").doubleValue());
89	        JsonArray jsonItems = rootObject.getJsonArray("items");
90	        List<OrderItem> items = new ArrayList<OrderItem>(jsonItems.size());
91	        for (JsonObject jsonItem : jsonItems.getValuesAs(JsonObject.class)) {
92	            OrderItem oi = new OrderItem();
93	            oi.setProductId(jsonItem.getString("productSku"));
94	            oi.setQuantity(jsonItem.getInt("quantity"));
95	            items.add(oi);
96	        }
97	        order.setItemList(items); 
98	        return order;
99	    }
