54		@Path("/{cartId}/{itemId}/{quantity}")
55		@Produces(MediaType.APPLICATION_JSON)
56		public ShoppingCart add(@PathParam("cartId") String cartId,
57								@PathParam("itemId") String itemId,
58								@PathParam("quantity") int quantity) {
59			ShoppingCart cart = shoppingCartService.getShoppingCart(cartId);
60	
61			Product product = shoppingCartService.getProduct(itemId);
62			if (product == null) {
63				throw new WebApplicationException("Product not found: " + itemId, Response.Status.NOT_FOUND);
64			}
65	
66			ShoppingCartItem sci = new ShoppingCartItem();
67			sci.setProduct(product);
68			sci.setQuantity(quantity);
69			sci.setPrice(product.getPrice());
70			cart.addShoppingCartItem(sci);
71	
72			try {
73				shoppingCartService.priceShoppingCart(cart);
74				cart.setShoppingCartItemList(dedupeCartItems(cart.getShoppingCartItemList()));
75			} catch (RuntimeException ex) {
76				log.warning("Failed to price cart " + cartId + ", rolling back item addition: " + ex.getMessage());
77				cart.removeShoppingCartItem(sci);
78				throw new WebApplicationException("Failed to price cart", ex, Response.Status.INTERNAL_SERVER_ERROR);
79			}
80	
81			return cart;
82		}
